// Package cmd contains the CLI commands for the kustomize-build command.
package cmd

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/gertd/go-pluralize"

	"github.com/spf13/cobra"
	"gopkg.in/yaml.v3"
	"k8s.io/utils/strings/slices"
	"sigs.k8s.io/kustomize/kustomize/v4/commands/build"
	"sigs.k8s.io/kustomize/kyaml/filesys"
)

const (
	fieldKind     = "kind"
	fieldMetadata = "metadata"

	defaultKustomizePath    = "config/kustomize"
	defaultOutputPath       = "config/kubernetes"
	overlaysDir             = "overlays"
	generatedReadmeFileName = "README.md"
	generatedYAMLComment    = "# This file was generated with Kustomize. Please do not edit manually."
	envReadmeContents       = "# Configuration for `{env}` environment\n\n" +
		"The configuration in this directory was autogenerated with Kustomize.\n\n" +
		"It contains the configuration for the **{env}** environment.\n\n" +
		"Please avoid editing the files in this directory directly, " +
		"as they will be overwritten by the next generation.\n\n" +
		"To learn more about how to use [Kustomize](https://kustomize.io/) at GitHub, please visit " +
		"[Kustomize on The Hub](https://thehub.github.com/epd/engineering/products-and-services/internal/moda/kustomize/).\n"
)

type buildCmdArgs struct {
	Environments string
	OutputDir    string
	DryRun       bool
}

var cmdArgs = buildCmdArgs{}

// BuildCmd Cobra build command.
var BuildCmd = setupBuildCmd()

// getBuildCmd returns a cobra command that builds kustomize resources.
func setupBuildCmd() *cobra.Command {
	buildCmd := &cobra.Command{
		Use: "build [path/to/repo]",
		Example: "build path/to/repo -e dev,prod --output path/to/output" +
			"\nbuild my/custom/path" +
			"\nbuild my/custom/path --output /output/path" +
			"\nbuild my/custom/path --dry" +
			"\nbuild my/custom/path -e default,prod",
		Short: "Build Kubernetes resources from Kustomize configs",
		Long: `Build a set of Kubernetes resources using Kustomize. Run this command from your repository root directory.
The 'path' argument must be a path to a local repository. 
If 'path' is omitted, 'path' is assumed '.'`,
		RunE:         getKustomizeBuildCmd(),
		SilenceUsage: true,
	}
	buildCmd.Flags().StringVarP(
		&cmdArgs.Environments,
		"environments",
		"e",
		"",
		"Comma separated list of environments to build",
	)

	buildCmd.Flags().StringVarP(
		&cmdArgs.OutputDir,
		"output",
		"o",
		"",
		"Output directory for generated resources",
	)

	buildCmd.Flags().BoolVarP(
		&cmdArgs.DryRun,
		"dry",
		"d",
		false,
		"Prints the generated resources to stdout (no files are written)",
	)

	RootCmd.AddCommand(buildCmd)

	return buildCmd
}

// getKustomizeBuildCmd returns a cobra command that builds kustomize resources.
func getKustomizeBuildCmd() func(cmd *cobra.Command, args []string) error {
	return func(cmd *cobra.Command, args []string) error {
		if err := validateBuildFlags(); err != nil {
			return err
		}

		outputPath, kustConfigPath, err := getAbsPaths(args, cmdArgs.OutputDir)
		if err != nil {
			return err
		}

		if err := validateConfigPath(kustConfigPath); err != nil {
			return err
		}

		return buildOverlays(cmd, outputPath, kustConfigPath+"/"+overlaysDir)
	}
}

// buildOverlays builds the overlays for the given environments.
func buildOverlays(cmd *cobra.Command, outputPath, overlaysPath string) error {
	kustomizeCmd, outputFile, err := newKustomizeBuildCmd()
	if err != nil {
		return err
	}

	var kustomizeOverlays []os.DirEntry
	if kustomizeOverlays, err = getOverlays(overlaysPath); err != nil {
		return err
	}

	envs := getEnvs(cmdArgs.Environments)
	if err := validateEnvs(kustomizeOverlays, envs); err != nil {
		return err
	}

	for _, overlay := range kustomizeOverlays {
		overlayName := overlay.Name()

		if len(envs) > 0 && !slices.Contains(envs, overlayName) {
			continue
		}

		overlayPath := outputPath + "/" + overlayName

		if !cmdArgs.DryRun {
			cleanUpDirectory(cmd, overlayPath)
		}

		if err := runKustomizeBuild(cmd, kustomizeCmd, overlaysPath+"/"+overlayName, overlay); err != nil {
			return fmt.Errorf("failed to build overlay '%s': %w", overlayName, err)
		}

		if err = ensureResourcesCreated(outputFile); err != nil {
			cleanUpDirectory(cmd, overlayPath)

			return err
		}

		if err = iterateYAMLs(outputFile, overlayPath); err != nil {
			cleanUpDirectory(cmd, overlayPath)

			return err
		}

		if err = writeReadmeFile(overlayPath, overlayName); err != nil {
			cleanUpDirectory(cmd, overlayPath)

			return fmt.Errorf("error writing README file: %w", err)
		}

		if err := resetFile(outputFile); err != nil {
			cleanUpDirectory(cmd, overlayPath)

			return err
		}

		if !cmdArgs.DryRun {
			cmd.Println("Done.")
		}
	}

	return nil
}

// runKustomizeBuild runs the kustomize build command and prints the status.
func runKustomizeBuild(cmd, kustomizeCmd *cobra.Command, overlayBasePath string, overlay os.DirEntry) error {
	dryRunMsg := ""
	if cmdArgs.DryRun {
		dryRunMsg = " (dry run)"
	}

	cmd.Printf("Building environment '%s' into %s%s... ", overlay.Name(), overlayBasePath, dryRunMsg)

	// enable Helm chart support with helmChartInflationGenerator
	if err := kustomizeCmd.ParseFlags([]string{"--enable-helm"}); err != nil {
		return err
	}
	return kustomizeCmd.RunE(kustomizeCmd, []string{overlayBasePath})
}

// ensureResourcesCreated ensures that the resources were created.
func ensureResourcesCreated(outputFile *os.File) error {
	var fileInfo os.FileInfo
	fileInfo, err := outputFile.Stat()
	if err != nil {
		return err
	}

	if fileInfo.Size() == 0 {
		return errors.New("kustomize did not generate any resources")
	}

	return nil
}

// validateBuildFlags validates the command flags.
func validateBuildFlags() error {
	if cmdArgs.OutputDir != "" && cmdArgs.DryRun {
		return errors.New("cannot use --output and --dry together")
	}

	return nil
}

// newKustomizeBuildCmd constructs a new kustomize build command.
func newKustomizeBuildCmd() (*cobra.Command, *os.File, error) {
	kustomizeHelp := build.MakeHelp("kustomize", "kustomize")

	outputFile, err := os.CreateTemp(os.TempDir(), "kustomize")
	if err != nil {
		return nil, nil, fmt.Errorf("failed to create temporary file: %w", err)
	}

	return build.NewCmdBuild(
		filesys.MakeFsOnDisk(),
		&build.Help{
			Use:     kustomizeHelp.Use,
			Short:   kustomizeHelp.Short,
			Long:    kustomizeHelp.Long,
			Example: kustomizeHelp.Example,
		}, outputFile), outputFile, nil
}

// resetFile resets the file to the beginning without deletion.
func resetFile(tempFile *os.File) error {
	if err := tempFile.Truncate(0); err != nil {
		return fmt.Errorf("failed to truncate temporary file: %w", err)
	}

	if _, err := tempFile.Seek(0, 0); err != nil {
		return fmt.Errorf("failed to reset temporary file: %w", err)
	}

	return nil
}

// validateEnvs validates that the given environments exists in the overlays' path.
func validateEnvs(overlays []os.DirEntry, environments []string) error {
	if len(environments) == 0 {
		return nil
	}

	for _, env := range environments {
		if !slices.Contains(getOverlayNames(overlays), env) {
			return fmt.Errorf(
				"environment '%s' does not exist (detected: %s)",
				env,
				strings.Join(getOverlayNames(overlays), ", "),
			)
		}
	}

	return nil
}

// getOverlayNames returns a list of overlay names.
func getOverlayNames(overlays []os.DirEntry) []string {
	names := make([]string, len(overlays))
	for i, overlay := range overlays {
		names[i] = overlay.Name()
	}

	return names
}

// getEnvs returns a list of environments from a comma-separated string.
func getEnvs(envsArg string) []string {
	if envsArg == "" {
		return []string{}
	}

	return strings.Split(envsArg, ",")
}

// getOverlays returns a list of kustomize overlays in the given path.
func getOverlays(overlaysPath string) ([]os.DirEntry, error) {
	if _, err := os.Stat(overlaysPath); os.IsNotExist(err) {
		return nil, fmt.Errorf("unable to locate overlays directory in %s", overlaysPath)
	}

	overlays, err := os.ReadDir(overlaysPath)
	if err != nil {
		return nil, fmt.Errorf("unable to read overlays directory in %s", overlaysPath)
	}

	if len(overlays) == 0 {
		return nil, fmt.Errorf("no overlays found in %s", overlaysPath)
	}

	return overlays, nil
}

// validateConfigPath checks if the given path is a valid kustomize config path.
func validateConfigPath(kustConfigPath string) error {
	if _, err := os.Stat(kustConfigPath); os.IsNotExist(err) {
		return fmt.Errorf("unable to locate kustomize config directory in %s: %w", kustConfigPath, err)
	}

	return nil
}

// getAbsPaths returns the absolute paths for the given arguments.
func getAbsPaths(args []string, outputDir string) (output, config string, err error) {
	var workingDir string

	outputPath := defaultOutputPath
	kustConfigPath := defaultKustomizePath

	switch len(args) {
	case 0:
		workingDir = "."
	case 1:
		workingDir = args[0]
	default:
		return "", "", errors.New("too many arguments")
	}

	if outputDir != "" {
		outputPath = outputDir
	}

	if outputPath, err = filepath.Abs(workingDir + "/" + outputPath); err != nil {
		return "", "", fmt.Errorf("unable to get absolute path of %s: %w", outputPath, err)
	}

	if kustConfigPath, err = filepath.Abs(workingDir + "/" + kustConfigPath); err != nil {
		return "", "", fmt.Errorf("unable to get absolute path of %s: %w", kustConfigPath, err)
	}

	return outputPath, kustConfigPath, nil
}

// getYAMLDecoder creates yaml decoder for provided source file.
func getYAMLDecoder(sourceYaml string) (*yaml.Decoder, error) {
	var yamlBytes []byte
	var err error
	if yamlBytes, err = os.ReadFile(sourceYaml); err != nil {
		return nil, fmt.Errorf("error reading YAML file: %v: %w", sourceYaml, err)
	}

	return yaml.NewDecoder(bytes.NewReader(yamlBytes)), nil
}

// iterateYAMLs iterates over the YAML documents and writes them to the output directory.
func iterateYAMLs(outputFile *os.File, outputDir string) error {
	var decoder *yaml.Decoder
	var err error

	if decoder, err = getYAMLDecoder(outputFile.Name()); err != nil {
		return err
	}

	for {
		var fileContents map[string]interface{}
		err := decoder.Decode(&fileContents)
		if errors.Is(err, io.EOF) {
			break
		}

		if err != nil {
			return fmt.Errorf("error decoding YAML: %w", err)
		}

		if err = ensureFields(fileContents); err != nil {
			return fmt.Errorf("missing fields found in YAML: %w", err)
		}

		valueBytes, err := yaml.Marshal(fileContents)
		if err != nil {
			return fmt.Errorf("error marshaling YAML: %w", err)
		}
		parentDir, filePath, shortPath, err := getPaths(fileContents, outputDir)
		if err != nil {
			return fmt.Errorf("error getting paths: %w", err)
		}

		if cmdArgs.DryRun {
			delim := strings.Repeat("-", 5)
			fmt.Printf("%s %s %s\n%s\n", delim, shortPath, delim, valueBytes)

			continue
		}

		valueBytes = append([]byte(generatedYAMLComment+"\n"), valueBytes...)

		if err = writeYAML(parentDir, filePath, valueBytes); err != nil {
			return fmt.Errorf("error writing YAML: %w", err)
		}
	}

	return nil
}

// writeYAML writes the given YAML bytes to the given file path.
func writeYAML(parentDir, filePath string, valueBytes []byte) error {
	if err := createDir(parentDir); err != nil {
		return err
	}

	if err := os.WriteFile(filePath, valueBytes, 0o600); err != nil {
		return fmt.Errorf("error writing file %s: %w", filePath, err)
	}

	return nil
}

// createDir creates a directory if it does not exist.
func createDir(parentDir string) error {
	if err := os.MkdirAll(parentDir, 0o750); err != nil {
		return fmt.Errorf("error creating directory: %v: %w", parentDir, err)
	}

	return nil
}

// cleanUpDirectory removes the output directory if it's empty.
func cleanUpDirectory(cmd *cobra.Command, outputDir string) {
	_ = os.RemoveAll(outputDir)
	cmd.Println("Cleaning up output directory...")
}

// ensureFields ensures that the YAML has the required fields.
func ensureFields(value map[string]interface{}) error {
	if _, ok := value[fieldKind]; !ok {
		return fmt.Errorf("field %s not found", fieldKind)
	}

	if _, ok := value[fieldMetadata]; !ok {
		return fmt.Errorf("field %s not found", fieldMetadata)
	}

	if _, ok := value[fieldMetadata].(map[string]interface{})["name"]; !ok {
		return fmt.Errorf("field %s not found", fieldMetadata+".name")
	}

	return nil
}

// getPaths returns the parent directory and filename for the YAML document.
func getPaths(value map[string]interface{}, dir string) (parent, path, short string, err error) {
	var hasField bool
	var kind string
	var fileName string
	var name string

	kind, hasField = value[fieldKind].(string)
	if !hasField {
		return "", "", "", fmt.Errorf("could not locate field '%s'", fieldKind)
	}

	name, hasField = value[fieldMetadata].(map[string]interface{})["name"].(string)
	if !hasField {
		return "", "", "", fmt.Errorf("could not locate field '%s'", fieldMetadata+".name")
	}

	fileName = name + "." + "yaml"
	kind = pluralize.NewClient().Pluralize(strings.ToLower(kind), 2, false)

	parentDir := fmt.Sprintf("%s/%s", dir, kind)
	filePath := fmt.Sprintf("%s/%s", parentDir, fileName)
	shortPath := fmt.Sprintf("%s/%s", kind, fileName)

	return parentDir, filePath, shortPath, nil
}

// writeReadmeFile writes the README file for the generated configurations.
func writeReadmeFile(envPath, envName string) error {
	readmeFile, err := os.Create(envPath + "/" + generatedReadmeFileName)
	if err != nil {
		return fmt.Errorf("error creating README file: %w", err)
	}

	defer func(readmeFile *os.File) {
		_ = readmeFile.Close()
	}(readmeFile)

	readmeContents := strings.ReplaceAll(envReadmeContents, "{env}", envName)
	if _, err := readmeFile.WriteString(readmeContents); err != nil {
		return fmt.Errorf("error generating README file: %w", err)
	}

	return nil
}
